export const KIND = {"id":58,"example":{"id":"E58","kind":58,"source":"aether","statement":["Write a function `walls::count_walls(const std::vector<std::string>& grid)` that returns a grid of the same size whose each square holds, as a digit, the number of `#` squares in the 3 rows and 3 columns around it, itself included.","The grid is a rectangle of rows of the same length; each square is `#` or `.`.","Limits: 0 ≤ rows ≤ 100; 0 ≤ length of each row ≤ 100."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <string>","#include <vector>","","namespace walls {","","bool is_wall(const std::vector<std::string>& grid, int r, int c)","{","    return r >= 0 && r < std::ssize(grid) && c >= 0","           && c < std::ssize(grid[r]) && grid[r][c] == '#';","}","","int walls_around(const std::vector<std::string>& grid, int row,","                 int column)","{","    int count {0};","    for (int r {row - 1}; r <= row + 1; ++r) {","        for (int c {column - 1}; c <= column + 1; ++c) {","            if (is_wall(grid, r, c)) {","                ++count;","            }","        }","    }","    return count;","}","","std::vector<std::string> count_walls(","    const std::vector<std::string>& grid)","{","    std::vector<std::string> result {grid};","    for (int r {0}; r < std::ssize(grid); ++r) {","        for (int c {0}; c < std::ssize(grid[r]); ++c) {","            result[r][c] = '0' + walls_around(grid, r, c);","        }","    }","    return result;","}","","}  // namespace walls"],"frame":[0,2,3,5,39],"labels":[{"at":7,"level":1,"text":"Write a function that gives back a value worked out in one step."},{"at":7,"level":0,"text":"Pass a grid as `const std::vector<std::string>&`, a list of strings, one string for each row."},{"at":9,"level":2,"text":"Give back whether the square is in the grid and holds a `#`."},{"at":9,"level":0,"text":"Get the character in row r and column c with `grid[r][c]`."},{"at":13,"level":1,"text":"Write a function that counts the items that pass a test and gives back the count."},{"at":16,"level":2,"text":"Start the count at zero."},{"at":17,"level":2,"text":"Add one for each wall in the 3 rows and 3 columns around it."},{"at":17,"level":0,"text":"Put a `for` inside a `for`, so the inner one runs in full at each step of the outer one."},{"at":24,"level":2,"text":"Give back the count."},{"at":27,"level":1,"text":"Write a function that builds a new grid from the answer for each square of the old one."},{"at":30,"level":2,"text":"Start the result as a copy of the grid."},{"at":31,"level":2,"text":"Put the count of walls around each square in its place."},{"at":33,"level":0,"text":"Turn a number from 0 to 9 into its digit with `'0' +`."},{"at":36,"level":2,"text":"Give back the result."}],"blanks":[]}},"trace":{"id":"T58","lines":["#include <iostream>","#include <print>","#include <string>","","int main()","{","    std::string row {};","    int column {0};","    std::cin >> row >> column;","    int count {0};","    for (int c {column - 1}; c <= column + 1; ++c) {","        if (c >= 0 && c < std::ssize(row) && row[c] == '#') {","            ++count;","        }","    }","    std::println(\"{}\", count);","}"],"columns":["row","column","count","c"],"inputs":["#.# 1\n","##.# 3\n"],"rows":[{"line":7,"values":["","","",""]},{"line":8,"values":["","0","",""]},{"line":9,"values":["#.#","1","",""]},{"line":10,"values":["#.#","1","0",""]},{"line":11,"values":["#.#","1","0","0"]},{"line":12,"values":["#.#","1","0","0"]},{"line":13,"values":["#.#","1","1","0"]},{"line":11,"values":["#.#","1","1","1"]},{"line":12,"values":["#.#","1","1","1"]},{"line":11,"values":["#.#","1","1","2"]},{"line":12,"values":["#.#","1","1","2"]},{"line":13,"values":["#.#","1","2","2"]},{"line":11,"values":["#.#","1","2",""]},{"line":16,"values":["#.#","1","2",""]}],"output":"1\n"},"traces":[],"problems":{"58.01":{"id":"58.01","kind":58,"source":"exercism","statement":["Write a function `flower_field::annotate(const std::vector<std::string>& garden)` that returns the garden with a number in each empty square.","The garden is a rectangle of rows of the same length; each square is a space (empty) or `*` (a flower).","In the result each flower stays, and each empty square holds the number of flowers in the up to 8 squares around it, side by side or corner to corner, as a digit; an empty square with no flower around it stays a space.","No rows give no rows, and empty rows stay empty.","Limits: 0 ≤ rows ≤ 100; 0 ≤ length of each row ≤ 100."],"examples":[{"input":"no rows","output":""}],"tests":[{"input":"no columns","output":""},{"input":"no flowers","output":""},{"input":"garden full of flowers","output":""},{"input":"flower surrounded by spaces","output":""},{"input":"space surrounded by flowers","output":""},{"input":"horizontal line","output":""},{"input":"horizontal line, flowers at edges","output":""},{"input":"vertical line","output":""},{"input":"vertical line, flowers at edges","output":""},{"input":"cross","output":""},{"input":"large garden","output":""},{"input":"multiple adjacent flowers","output":""}],"solution":{"lines":["#pragma once","","#include <string>","#include <vector>","","namespace flower_field {","","bool is_flower(const std::vector<std::string>& garden,","               int r, int c)","{","    return r >= 0 && r < std::ssize(garden) && c >= 0","           && c < std::ssize(garden[r]) && garden[r][c] == '*';","}","","int flowers_around(const std::vector<std::string>& garden,","                   int row, int column)","{","    int count {0};","    for (int r {row - 1}; r <= row + 1; ++r) {","        for (int c {column - 1}; c <= column + 1; ++c) {","            if (is_flower(garden, r, c)) {","                ++count;","            }","        }","    }","    return count;","}","","std::vector<std::string> annotate(","    const std::vector<std::string>& garden)","{","    std::vector<std::string> result {garden};","    for (int r {0}; r < std::ssize(garden); ++r) {","        for (int c {0}; c < std::ssize(garden[r]); ++c) {","            const int count {flowers_around(garden, r, c)};","            if (garden[r][c] == ' ' && count > 0) {","                result[r][c] = '0' + count;","            }","        }","    }","    return result;","}","","}  // namespace flower_field"],"frame":[0,2,3,5,43],"labels":[{"at":7,"level":1,"text":"Write a function that gives back a value worked out in one step."},{"at":10,"level":2,"text":"Give back whether the square is in the garden and holds a flower."},{"at":14,"level":1,"text":"Write a function that counts the items that pass a test and gives back the count."},{"at":17,"level":2,"text":"Start the count at zero."},{"at":18,"level":2,"text":"Add one for each flower in the 3 rows and 3 columns around it."},{"at":25,"level":2,"text":"Give back the count."},{"at":28,"level":1,"text":"Write a function that builds a new grid from the answer for each square of the old one."},{"at":31,"level":2,"text":"Start the result as a copy of the garden."},{"at":32,"level":2,"text":"Put the count of flowers around each empty square, when above 0."},{"at":40,"level":2,"text":"Give back the result."}],"blanks":[{"line":8,"from":15,"to":27},{"line":11,"from":43,"to":62},{"line":15,"from":19,"to":38},{"line":17,"from":15,"to":16},{"line":20,"from":16,"to":39},{"line":25,"from":11,"to":16},{"line":29,"from":4,"to":42},{"line":31,"from":37,"to":43},{"line":35,"from":39,"to":48},{"line":40,"from":11,"to":17}]},"fn":{"slug":"flower-field","commit":"8d139cb0","header":"flower_field.h","name":"flower_field_test.cpp","test":"#include \"flower_field.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n\n/*\n The expected outputs are represented as arrays of strings to\n improve readability in this JSON file.\n Your track may choose whether to present the input as a single\n string (concatenating all the lines) or as the list.\n*/\n\nTEST_CASE(\"no rows\", \"[237ff487-467a-47e1-9b01-8a891844f86c]\") {\n    const std::vector<std::string> expected{};\n    REQUIRE(expected == flower_field::annotate({}));\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\n\nTEST_CASE(\"no columns\", \"[4b4134ec-e20f-439c-a295-664c38950ba1]\") {\n    const std::vector<std::string> expected{\"\"};\n    REQUIRE(expected == flower_field::annotate({\"\"}));\n}\n\nTEST_CASE(\"no flowers\", \"[d774d054-bbad-4867-88ae-069cbd1c4f92]\") {\n    const std::vector<std::string> expected{\"   \", \"   \", \"   \"};\n    REQUIRE(expected == flower_field::annotate({\"   \", \"   \", \"   \"}));\n}\n\nTEST_CASE(\"garden full of flowers\", \"[225176a0-725e-43cd-aa13-9dced501f16e]\") {\n    const std::vector<std::string> expected{\"***\", \"***\", \"***\"};\n    REQUIRE(expected == flower_field::annotate({\"***\", \"***\", \"***\"}));\n}\n\nTEST_CASE(\"flower surrounded by spaces\",\n          \"[3f345495-f1a5-4132-8411-74bd7ca08c49]\") {\n    const std::vector<std::string> expected{\"111\", \"1*1\", \"111\"};\n    REQUIRE(expected == flower_field::annotate({\"   \", \" * \", \"   \"}));\n}\n\nTEST_CASE(\"space surrounded by flowers\",\n          \"[6cb04070-4199-4ef7-a6fa-92f68c660fca]\") {\n    const std::vector<std::string> expected{\"***\", \"*8*\", \"***\"};\n    REQUIRE(expected == flower_field::annotate({\"***\", \"* *\", \"***\"}));\n}\n\nTEST_CASE(\"horizontal line\", \"[272d2306-9f62-44fe-8ab5-6b0f43a26338]\") {\n    const std::vector<std::string> expected{\"1*2*1\"};\n    REQUIRE(expected == flower_field::annotate({\" * * \"}));\n}\n\nTEST_CASE(\"horizontal line, flowers at edges\",\n          \"[c6f0a4b2-58d0-4bf6-ad8d-ccf4144f1f8e]\") {\n    const std::vector<std::string> expected{\"*1 1*\"};\n    REQUIRE(expected == flower_field::annotate({\"*   *\"}));\n}\n\nTEST_CASE(\"vertical line\", \"[a54e84b7-3b25-44a8-b8cf-1753c8bb4cf5]\") {\n    const std::vector<std::string> expected{\"1\", \"*\", \"2\", \"*\", \"1\"};\n    REQUIRE(expected == flower_field::annotate({\" \", \"*\", \" \", \"*\", \" \"}));\n}\n\nTEST_CASE(\"vertical line, flowers at edges\",\n          \"[b40f42f5-dec5-4abc-b167-3f08195189c1]\") {\n    const std::vector<std::string> expected{\"*\", \"1\", \" \", \"1\", \"*\"};\n    REQUIRE(expected == flower_field::annotate({\"*\", \" \", \" \", \" \", \"*\"}));\n}\n\nTEST_CASE(\"cross\", \"[58674965-7b42-4818-b930-0215062d543c]\") {\n    const std::vector<std::string> expected{\" 2*2 \", \"25*52\", \"*****\", \"25*52\",\n                                            \" 2*2 \"};\n    REQUIRE(expected == flower_field::annotate(\n                            {\"  *  \", \"  *  \", \"*****\", \"  *  \", \"  *  \"}));\n}\n\nTEST_CASE(\"large garden\", \"[dd9d4ca8-9e68-4f78-a677-a2a70fd7a7b8]\") {\n    const std::vector<std::string> expected{\"1*22*1\", \"12*322\", \" 123*2\",\n                                            \"112*4*\", \"1*22*2\", \"111111\"};\n    REQUIRE(expected == flower_field::annotate({\" *  * \", \"  *   \", \"    * \",\n                                                \"   * *\", \" *  * \", \"      \"}));\n}\n\nTEST_CASE(\"multiple adjacent flowers\",\n          \"[6e4ac13a-3e43-4728-a2e3-3551d4b1a996]\") {\n    const std::vector<std::string> expected{\"1**1\"};\n    REQUIRE(expected == flower_field::annotate({\" ** \"}));\n}\n#endif\n","setup":["const std::vector<std::string> expected{};"],"calls":[{"call":"flower_field::annotate({})","expected":"expected"}]}},"58.02":{"id":"58.02","kind":58,"source":"aether","statement":["Write a function `side_count::annotate(const std::vector<std::string>& grid)` that returns a grid of the same size whose each square holds, as a digit, the number of `#` squares directly above, below, left and right of it.","The grid is a rectangle of rows of the same length; each square is `#` or `.`.","No rows give no rows, and empty rows stay empty.","Limits: 0 ≤ rows ≤ 100; 0 ≤ length of each row ≤ 100."],"examples":[{"input":"two by two","output":""}],"tests":[{"input":"no rows","output":""},{"input":"empty row","output":""},{"input":"one wall","output":""},{"input":"no walls","output":""},{"input":"all walls","output":""},{"input":"corners do not count","output":""},{"input":"one row","output":""},{"input":"one column","output":""},{"input":"largest","output":""}],"solution":{"lines":["#pragma once","","#include <cstdlib>","#include <string>","#include <vector>","","namespace side_count {","","bool is_wall(const std::vector<std::string>& grid,","             int r, int c)","{","    return r >= 0 && r < std::ssize(grid) && c >= 0","           && c < std::ssize(grid[r]) && grid[r][c] == '#';","}","","int walls_beside(const std::vector<std::string>& grid,","                 int row, int column)","{","    int count {0};","    for (int r {row - 1}; r <= row + 1; ++r) {","        for (int c {column - 1}; c <= column + 1; ++c) {","            const int apart {std::abs(r - row)","                             + std::abs(c - column)};","            if (apart == 1 && is_wall(grid, r, c)) {","                ++count;","            }","        }","    }","    return count;","}","","std::vector<std::string> annotate(","    const std::vector<std::string>& grid)","{","    std::vector<std::string> result {grid};","    for (int r {0}; r < std::ssize(grid); ++r) {","        for (int c {0}; c < std::ssize(grid[r]); ++c) {","            result[r][c] = '0' + walls_beside(grid, r, c);","        }","    }","    return result;","}","","}  // namespace side_count"],"frame":[0,2,3,4,6,43],"labels":[{"at":8,"level":1,"text":"Write a function that gives back a value worked out in one step."},{"at":11,"level":2,"text":"Give back whether the square is in the grid and holds a `#`."},{"at":15,"level":1,"text":"Write a function that counts the items that pass a test and gives back the count."},{"at":18,"level":2,"text":"Start the count at zero."},{"at":19,"level":2,"text":"Add one for each wall directly above, below, left or right of it."},{"at":28,"level":2,"text":"Give back the count."},{"at":31,"level":1,"text":"Write a function that builds a new grid from the answer for each square of the old one."},{"at":34,"level":2,"text":"Start the result as a copy of the grid."},{"at":35,"level":2,"text":"Put the count of walls beside each square in its place."},{"at":40,"level":2,"text":"Give back the result."}],"blanks":[{"line":9,"from":13,"to":25},{"line":12,"from":41,"to":58},{"line":16,"from":17,"to":36},{"line":18,"from":15,"to":16},{"line":23,"from":30,"to":49},{"line":28,"from":11,"to":16},{"line":32,"from":4,"to":40},{"line":34,"from":37,"to":41},{"line":37,"from":33,"to":57},{"line":40,"from":11,"to":17}]},"fn":{"slug":"side_count","commit":"","header":"side_count.h","name":"side_count_test.cpp","test":"#include \"side_count.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"two by two\") {\n    const std::vector<std::string> grid {\"#.\", \"..\"};\n    const std::vector<std::string> expected {\"01\", \"10\"};\n    REQUIRE(side_count::annotate(grid) == expected);\n}\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"no rows\") {\n    const std::vector<std::string> grid {};\n    REQUIRE(side_count::annotate(grid).empty());\n}\nTEST_CASE(\"empty row\") {\n    const std::vector<std::string> grid {\"\"};\n    const std::vector<std::string> expected {\"\"};\n    REQUIRE(side_count::annotate(grid) == expected);\n}\nTEST_CASE(\"one wall\") {\n    const std::vector<std::string> grid {\"#\"};\n    const std::vector<std::string> expected {\"0\"};\n    REQUIRE(side_count::annotate(grid) == expected);\n}\nTEST_CASE(\"no walls\") {\n    const std::vector<std::string> grid {\"...\", \"...\"};\n    const std::vector<std::string> expected {\"000\", \"000\"};\n    REQUIRE(side_count::annotate(grid) == expected);\n}\nTEST_CASE(\"all walls\") {\n    const std::vector<std::string> grid {\"###\", \"###\", \"###\"};\n    const std::vector<std::string> expected {\"232\", \"343\", \"232\"};\n    REQUIRE(side_count::annotate(grid) == expected);\n}\nTEST_CASE(\"corners do not count\") {\n    const std::vector<std::string> grid {\"#.#\", \"...\", \"#.#\"};\n    const std::vector<std::string> expected {\"020\", \"202\", \"020\"};\n    REQUIRE(side_count::annotate(grid) == expected);\n}\nTEST_CASE(\"one row\") {\n    const std::vector<std::string> grid {\"#.#\"};\n    const std::vector<std::string> expected {\"020\"};\n    REQUIRE(side_count::annotate(grid) == expected);\n}\nTEST_CASE(\"one column\") {\n    const std::vector<std::string> grid {\"#\", \".\", \"#\"};\n    const std::vector<std::string> expected {\"0\", \"2\", \"0\"};\n    REQUIRE(side_count::annotate(grid) == expected);\n}\nTEST_CASE(\"largest\") {\n    const std::vector<std::string> grid(100, std::string(100, '#'));\n    const std::vector<std::string> result {side_count::annotate(grid)};\n    REQUIRE(result[0][0] == '2');\n    REQUIRE(result[0][50] == '3');\n    REQUIRE(result[50][50] == '4');\n    REQUIRE(result[99][99] == '2');\n}\n#endif\n","setup":["const std::vector<std::string> grid {\"#.\", \"..\"};","const std::vector<std::string> expected {\"01\", \"10\"};"],"calls":[{"call":"side_count::annotate(grid)","expected":"expected"}]}}}}
